import { NextResponse } from 'next/server';

const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const ROLES = new Set(['Artist', 'Curator', 'Cultural worker', 'Researcher', 'Educator', 'Organisation / institution', 'Student', 'Other']);
const INTERESTS = new Set(['Art & artistic practice', 'Decolonial research', 'Cultural institutions', 'Education', 'Archives & memory', 'Community / collective practice', 'Other']);

export async function POST(request: Request) {
  let body: { firstName?: unknown; email?: unknown; cityCountry?: unknown; describes?: unknown; website?: unknown; interested?: unknown; openQuestion?: unknown; consent?: unknown; honeypot?: unknown };
  try { body = await request.json(); } catch { return NextResponse.json({ error: 'invalid_request' }, { status: 400 }); }
  const firstName = typeof body.firstName === 'string' ? body.firstName.trim() : ''; const email = typeof body.email === 'string' ? body.email.trim().toLowerCase() : ''; const cityCountry = typeof body.cityCountry === 'string' ? body.cityCountry.trim() : ''; const describes = typeof body.describes === 'string' ? body.describes : ''; const website = typeof body.website === 'string' ? body.website.trim() : ''; const openQuestion = typeof body.openQuestion === 'string' ? body.openQuestion.trim() : ''; const interested = Array.isArray(body.interested) ? body.interested.filter((value): value is string => typeof value === 'string' && INTERESTS.has(value)) : [];
  if (body.honeypot || !firstName || firstName.length > 100 || !EMAIL.test(email) || !cityCountry || cityCountry.length > 120 || !ROLES.has(describes) || website.length > 240 || openQuestion.length > 2000 || body.consent !== true) return NextResponse.json({ error: 'invalid_subscription' }, { status: 400 });
  const apiKey = process.env.BREVO_API_KEY; const listId = Number(process.env.BREVO_COMMUNITY_LIST_ID); if (!apiKey || !Number.isInteger(listId) || listId <= 0) return NextResponse.json({ error: 'community_not_configured' }, { status: 503 });
  const attributes: Record<string, string | string[]> = { FIRSTNAME: firstName, CITY: cityCountry, DESCRIBES: describes }; if (website) attributes.WEBSITE = website; if (openQuestion) attributes.OPEN_QUESTION = openQuestion; if (interested.length) attributes.INTERESTED = interested;
  const response = await fetch('https://api.brevo.com/v3/contacts', { method: 'POST', headers: { accept: 'application/json', 'api-key': apiKey, 'content-type': 'application/json' }, body: JSON.stringify({ email, attributes, listIds: [listId], updateEnabled: true }), cache: 'no-store' }); if (!response.ok) return NextResponse.json({ error: 'community_provider_error' }, { status: 502 }); return NextResponse.json({ ok: true });
}
